<script setup lang="ts">
import { useLocale } from '../../locales';
const { translate } = useLocale();
import {ref,computed} from 'vue';import {useRoute} from 'vue-router';import {Plus,ChevronLeft,ChevronRight,LayoutGrid,List,X} from 'lucide-vue-next';import WorkshopHeader from '../../components/WorkshopHeader.vue';import StatusBadge from '../../components/StatusBadge.vue';import {useWorkshop} from '../../composables/useWorkshop';import type {BookingStatus} from '../../data/company';const {state,setBookingStatus,addBooking}=useWorkshop();const view=ref<'Day'|'Week'>('Day');const route=useRoute();const selected=ref(typeof route.query.date==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(route.query.date)?route.query.date:'2026-08-26');const adding=ref(false);const form=ref({time:'15:00',duration:'1h',customer:'New customer',vehicle:'BMW 118i',registration:'LJ NC-101',service:'Regular service',technician:'Luka Zupan',bay:'Lift 3'});const statusOptions:BookingStatus[]=['Requested','Confirmed','Arrived','In workshop','Waiting approval','Ready','Completed','Cancelled'];const shown=computed(()=>view.value==='Day'?state.bookings.filter(b=>b.date===selected.value):state.bookings);const save=()=>{addBooking({id:crypto.randomUUID(),date:selected.value,...form.value,status:'Confirmed',source:'Manual'});adding.value=false}
</script>
<template><WorkshopHeader :title="translate('Calendar')" :subtitle="translate('Servis Ljubljana')"><button @click="adding=true" class="btn-primary !min-h-10"><Plus :size="16"/>{{ translate("Booking") }}</button></WorkshopHeader><div class="mx-auto max-w-[1400px] p-5 md:p-8"><div class="flex flex-wrap items-center justify-between gap-4"><div class="flex items-center gap-2"><button class="btn-secondary !min-h-10 !px-3"><ChevronLeft :size="17"/></button><input v-model="selected" type="date" class="field nums w-auto"/><button class="btn-secondary !min-h-10 !px-3"><ChevronRight :size="17"/></button></div><div class="flex rounded-xl border bg-white p-1"><button v-for="v in ['Day','Week']" @click="view=v as 'Day'|'Week'" class="flex items-center gap-2 rounded-lg px-4 py-2 text-sm font-medium" :class="view===v?'bg-ink text-white':''"><component :is="v==='Day'?List:LayoutGrid" :size="16"/>{{ translate((v)) }}</button></div></div><div class="mt-6 overflow-hidden rounded-2xl border bg-white"><div class="hidden grid-cols-[80px_1fr_150px_140px_160px] gap-4 border-b bg-stone-50 px-5 py-3 text-xs font-semibold text-muted md:grid"><span>{{ translate("Time") }}</span><span>{{ translate("Booking") }}</span><span>{{ translate("Technician") }}</span><span>{{ translate("Bay") }}</span><span>{{ translate("Status") }}</span></div><div v-for="b in shown" class="grid gap-3 border-b p-5 last:border-0 md:grid-cols-[80px_1fr_150px_140px_160px] md:items-center md:gap-4"><span class="nums font-semibold">{{ translate((b.time)) }}<small class="block font-normal text-muted">{{ translate((b.duration)) }}</small></span><span><strong class="block text-sm">{{ translate((b.vehicle) + " · " + (b.registration)) }}</strong><small class="text-muted">{{ translate((b.customer) + " · " + (b.service) + " · " + (b.source)) }}</small></span><span class="text-sm">{{ translate((b.technician)) }}</span><span class="text-sm text-muted">{{ translate((b.bay)) }}</span><select :value="b.status" @change="setBookingStatus