r'">{{ translate("Marko Vidmar") }}</option></select></label><label><span class="label">{{ translate("Bay / lift") }}</span><input v-model="form.bay" class="field"/></label></div><button class="btn-primary mt-6 w-full">{{ translate("Create booking") }}</button></form></div></Teleport></template>
